from contextlib import asynccontextmanager
from enum import Enum
import sqlite3
from pathlib import Path
from typing import Annotated

from fastapi import FastAPI, HTTPException, Query
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel, Field

DB_PATH = Path(__file__).with_name("books.db")


class BookStatus(str, Enum):
    TO_READ = "to-read"
    READING = "reading"
    DONE = "done"


class BookCreate(BaseModel):
    title: str = Field(min_length=1, max_length=300)
    author: str = Field(min_length=1, max_length=300)
    status: BookStatus = BookStatus.TO_READ


class BookUpdateStatus(BaseModel):
    status: BookStatus


class Book(BaseModel):
    id: int
    title: str
    author: str
    status: BookStatus


def get_connection() -> sqlite3.Connection:
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db() -> None:
    with get_connection() as conn:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS books (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                author TEXT NOT NULL,
                status TEXT NOT NULL CHECK(status IN ('to-read', 'reading', 'done')),
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            )
            """
        )
        conn.commit()


@asynccontextmanager
async def lifespan(app: FastAPI):
    init_db()
    yield


app = FastAPI(title="BookTrack API", lifespan=lifespan)

app.add_middleware(
    CORSMiddleware,
    allow_origins=["http://localhost:5173", "http://127.0.0.1:5173"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)


def row_to_book(row: sqlite3.Row) -> Book:
    return Book(id=row["id"], title=row["title"], author=row["author"], status=row["status"])


@app.get("/health")
def health() -> dict[str, str]:
    return {"status": "ok"}


@app.get("/books", response_model=list[Book])
def list_books(status: Annotated[BookStatus | None, Query()] = None) -> list[Book]:
    with get_connection() as conn:
        if status is None:
            rows = conn.execute("SELECT * FROM books ORDER BY id DESC").fetchall()
        else:
            rows = conn.execute(
                "SELECT * FROM books WHERE status = ? ORDER BY id DESC", (status.value,)
            ).fetchall()
    return [row_to_book(row) for row in rows]


@app.post("/books", response_model=Book, status_code=201)
def create_book(payload: BookCreate) -> Book:
    title = payload.title.strip()
    author = payload.author.strip()
    if not title or not author:
        raise HTTPException(status_code=422, detail="Title and author are required")

    with get_connection() as conn:
        cursor = conn.execute(
            "INSERT INTO books (title, author, status) VALUES (?, ?, ?)",
            (title, author, payload.status.value),
        )
        conn.commit()
        row = conn.execute("SELECT * FROM books WHERE id = ?", (cursor.lastrowid,)).fetchone()

    if row is None:
        raise HTTPException(status_code=500, detail="Could not create book")
    return row_to_book(row)


@app.patch("/books/{book_id}/status", response_model=Book)
def update_book_status(book_id: int, payload: BookUpdateStatus) -> Book:
    with get_connection() as conn:
        cursor = conn.execute(
            "UPDATE books SET status = ? WHERE id = ?", (payload.status.value, book_id)
        )
        if cursor.rowcount == 0:
            raise HTTPException(status_code=404, detail="Book not found")
        conn.commit()
        row = conn.execute("SELECT * FROM books WHERE id = ?", (book_id,)).fetchone()

    if row is None:
        raise HTTPException(status_code=404, detail="Book not found")
    return row_to_book(row)

import React, { useEffect, useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import './styles.css'

const API_URL = import.meta.env.VITE_API_URL ?? 'http://localhost:8000'

const statuses = [
  { value: 'to-read', label: 'Da leggere' },
  { value: 'reading', label: 'In lettura' },
  { value: 'done', label: 'Finito' },
]

function statusLabel(value) {
  return statuses.find((status) => status.value === value)?.label ?? value
}

function App() {
  const [books, setBooks] = useState([])
  const [title, setTitle] = useState('')
  const [author, setAuthor] = useState('')
  const [status, setStatus] = useState('to-read')
  const [filter, setFilter] = useState('all')
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  const filteredBooks = useMemo(() => {
    if (filter === 'all') return books
    return books.filter((book) => book.status === filter)
  }, [books, filter])

  async function loadBooks() {
    setLoading(true)
    setError('')
    try {
      const response = await fetch(`${API_URL}/books`)
      if (!response.ok) throw new Error('Errore nel caricamento dei libri')
      setBooks(await response.json())
    } catch (err) {
      setError(err.message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => {
    loadBooks()
  }, [])

  async function addBook(event) {
    event.preventDefault()
    setSaving(true)
    setError('')
    try {
      const response = await fetch(`${API_URL}/books`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title, author, status }),
      })
      if (!response.ok) throw new Error('Errore nel salvataggio del libro')
      const created = await response.json()
      setBooks((current) => [created, ...current])
      setTitle('')
      setAuthor('')
      setStatus('to-read')
    } catch (err) {
      setError(err.message)
    } finally {
      setSaving(false)
    }
  }

  async function changeStatus(bookId, nextStatus) {
    setError('')
    const previousBooks = books
    setBooks((current) =>
      current.map((book) => (book.id === bookId ? { ...book, status: nextStatus } : book)),
    )
    try {
      const response = await fetch(`${API_URL}/books/${bookId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: nextStatus }),
      })
      if (!response.ok) throw new Error('Errore durante il cambio status')
      const updated = await response.json()
      setBooks((current) => current.map((book) => (book.id === bookId ? updated : book)))
    } catch (err) {
      setBooks(previousBooks)
      setError(err.message)
    }
  }

  return (
    <main className="app">
      <header className="hero">
        <p className="eyebrow">Locale · senza login</p>
        <h1>BookTrack</h1>
        <p>Tieni traccia dei libri da leggere, in lettura e finiti.</p>
      </header>

      <section className="panel">
        <h2>Aggiungi libro</h2>
        <form onSubmit={addBook} className="form">
          <label>
            Titolo
            <input value={title} onChange={(event) => setTitle(event.target.value)} required />
          </label>
          <label>
            Autore
            <input value={author} onChange={(event) => setAuthor(event.target.value)} required />
          </label>
          <label>
            Status
            <select value={status} onChange={(event) => setStatus(event.target.value)}>
              {statuses.map((option) => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </label>
          <button disabled={saving}>{saving ? 'Salvataggio...' : 'Aggiungi'}</button>
        </form>
      </section>

      <section className="panel">
        <div className="listHeader">
          <h2>Lista libri</h2>
          <select value={filter} onChange={(event) => setFilter(event.target.value)}>
            <option value="all">Tutti</option>
            {statuses.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        </div>

        {error && <p className="error">{error}</p>}
        {loading && <p className="muted">Caricamento...</p>}
        {!loading && filteredBooks.length === 0 && <p className="muted">Nessun libro da mostrare.</p>}

        <div className="books">
          {filteredBooks.map((book) => (
            <article className="book" key={book.id}>
              <div>
                <h3>{book.title}</h3>
                <p>{book.author}</p>
                <span className={`badge ${book.status}`}>{statusLabel(book.status)}</span>
              </div>
              <label className="statusControl">
                Cambia status
                <select value={book.status} onChange={(event) => changeStatus(book.id, event.target.value)}>
                  {statuses.map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              </label>
            </article>
          ))}
        </div>
      </section>
    </main>
  )
}

createRoot(document.getElementById('root')).render(<App />)

:root {
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #1f2937;
  background: #f6f3ee;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  min-width: 320px;
}

button,
input,
select {
  font: inherit;
}

.app {
  width: min(980px, calc(100% - 32px));
  margin: 0 auto;
  padding: 40px 0;
}

.hero {
  margin-bottom: 24px;
  padding: 32px;
  border-radius: 28px;
  color: white;
  background: linear-gradient(135deg, #2f4858, #577590);
  box-shadow: 0 18px 50px rgba(47, 72, 88, 0.25);
}

.hero h1 {
  margin: 0 0 8px;
  font-size: clamp(2.5rem, 8vw, 5rem);
  letter-spacing: -0.06em;
}

.hero p {
  margin: 0;
  color: rgba(255, 255, 255, 0.84);
  font-size: 1.1rem;
}

.eyebrow {
  margin-bottom: 8px !important;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.75rem !important;
  font-weight: 700;
}

.panel {
  margin-top: 18px;
  padding: 24px;
  border: 1px solid rgba(31, 41, 55, 0.08);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 12px 35px rgba(31, 41, 55, 0.08);
}

.panel h2 {
  margin: 0 0 18px;
}

.form {
  display: grid;
  grid-template-columns: 1fr 1fr 180px auto;
  gap: 14px;
  align-items: end;
}

label {
  display: grid;
  gap: 7px;
  color: #4b5563;
  font-size: 0.9rem;
  font-weight: 700;
}

input,
select {
  width: 100%;
  border: 1px solid #d1d5db;
  border-radius: 14px;
  padding: 12px 13px;
  color: #111827;
  background: #fff;
}

input:focus,
select:focus {
  outline: 3px solid rgba(87, 117, 144, 0.22);
  border-color: #577590;
}

button {
  border: 0;
  border-radius: 14px;
  padding: 13px 18px;
  color: white;
  background: #2f4858;
  font-weight: 800;
  cursor: pointer;
}

button:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

.listHeader {
  display: flex;
  gap: 16px;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.listHeader h2 {
  margin: 0;
}

.listHeader select {
  max-width: 190px;
}

.books {
  display: grid;
  gap: 12px;
}

.book {
  display: flex;
  gap: 18px;
  justify-content: space-between;
  align-items: center;
  padding: 18px;
  border: 1px solid #ece7df;
  border-radius: 18px;
  background: #fffdf9;
}

.book h3 {
  margin: 0 0 5px;
  font-size: 1.15rem;
}

.book p {
  margin: 0 0 10px;
  color: #6b7280;
}

.badge {
  display: inline-flex;
  border-radius: 999px;
  padding: 5px 10px;
  font-size: 0.78rem;
  font-weight: 900;
}

.badge.to-read {
  color: #7c2d12;
  background: #ffedd5;
}

.badge.reading {
  color: #1e3a8a;
  background: #dbeafe;
}

.badge.done {
  color: #14532d;
  background: #dcfce7;
}

.statusControl {
  min-width: 180px;
}

.error {
  border-radius: 14px;
  padding: 12px 14px;
  color: #991b1b;
  background: #fee2e2;
}

.muted {
  color: #6b7280;
}

@media (max-width: 760px) {
  .form {
    grid-template-columns: 1fr;
  }

  .book,
  .listHeader {
    align-items: stretch;
    flex-direction: column;
  }

  .listHeader select,
  .statusControl {
    max-width: none;
    width: 100%;
  }
}
